package dev.cardadvisor.finance;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.web.server.LocalServerPort;import org.springframework.context.annotation.Import;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.jdbc.core.JdbcTemplate;import java.util.*;import java.util.concurrent.*;import java.nio.file.*;import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT,properties={"codef.config-file=","codef.storage-key-file=","openai.config-file=","account.mail-config-file="})
@Import(FinancialConnectionsPostgresTest.LocalProviderConfiguration.class)
@EnabledIfEnvironmentVariable(named="RUN_DEVICE_FREE_ANDROID_TEST",matches="true")
class AndroidMerchantMemoryPostgresTest{
 @LocalServerPort int port;@Autowired JdbcTemplate db;@Autowired FinancialConnectionsPostgresTest.Stub provider;
 String adb(String...args)throws Exception{var c=new ArrayList<String>(List.of(System.getenv("LOCALAPPDATA")+"/Android/Sdk/platform-tools/adb.exe","-s","emulator-5554"));c.addAll(List.of(args));var p=new ProcessBuilder(c).redirectErrorStream(true).start();var read=CompletableFuture.supplyAsync(()->{try{return new String(p.getInputStream().readAllBytes(),java.nio.charset.StandardCharsets.UTF_8);}catch(Exception e){return "";}});if(!p.waitFor(120,TimeUnit.SECONDS)){p.destroyForcibly();fail("Synthetic Android timeout");}assertEquals(0,p.exitValue());return read.get(3,TimeUnit.SECONDS);}
 @Test void merchantMemoryReadback()throws Exception{String run=UUID.randomUUID().toString();var b=new FinancialConnectionsPostgresTest.Behavior();var creation=new FinancialConnectionsPostgresTest.Behavior();b.approvalData=CodefApprovalNormalizerTest.row("MEMORYUI","50000","0","").put("resMemberStoreName","합성 가맹점");provider.calls.clear();provider.behaviors.clear();provider.behaviors.add(creation);provider.behaviors.add(b);var report=new LinkedHashMap<String,Object>();report.put("passed",false);report.put("physicalDevice",false);
  try{adb("reverse","tcp:18080","tcp:"+port);String result=adb("shell","am","instrument","-w","-r","-e","class","dev.cardadvisor.android.MerchantMemoryFlowTest","-e","runId",run,"dev.cardadvisor.android.test/androidx.test.runner.AndroidJUnitRunner");report.put("failureLocations",java.util.regex.Pattern.compile("MerchantMemoryFlowTest\\.kt:[0-9]+").matcher(result).results().map(java.util.regex.MatchResult::group).distinct().toList());assertTrue(result.contains("OK (1 test)"),"Synthetic reconciliation UI failed; raw output withheld");UUID user=db.queryForObject("SELECT id FROM app_users WHERE email=?",UUID.class,"merchant-ui-"+run+"@example.test");assertEquals(1,db.queryForObject("SELECT count(*) FROM merchant_category_rules WHERE user_id=? AND category IS NULL AND version=2",Integer.class,user));assertEquals(1,db.queryForObject("SELECT count(*) FROM ledger_entries WHERE user_id=?",Integer.class,user));assertEquals(50000,db.queryForObject("SELECT amount_won FROM ledger_entries WHERE user_id=?",Long.class,user));report.put("passed",true);
  }finally{db.update("DELETE FROM app_users WHERE email=?","merchant-ui-"+run+"@example.test");adb("reverse","--remove","tcp:18080");Files.writeString(Path.of("../.run/merchant-memory-android.json"),new com.fasterxml.jackson.databind.ObjectMapper().writeValueAsString(report));}
 }
}
